using MCPForUnity.Editor.Helpers;using MCPForUnity.Editor.Tools;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using P3.Validation;
[McpForUnityTool("p3_art_open_target",Description="Open a registered P3 art target")] public static class P3ArtOpenTargetTool{public static object HandleCommand(JObject p){try{var id=p?.Value<string>("target_id");var go=ArtTargetRegistry.Resolve(id);return new SuccessResponse("Art target reachable",new{target_id=id,name=go.name});}catch(System.Exception e){return new ErrorResponse(e.Message);}}}
[McpForUnityTool("p3_art_capture",Description="Copy and verify an art screenshot into an ArtRunID")] public static class P3ArtCaptureTool{public static object HandleCommand(JObject p){try{var run=p.Value<string>("run_id");var src=p.Value<string>("source_path");var dst=System.IO.Path.Combine(EvidencePaths.ForArtRun(run).Screenshots,System.IO.Path.GetFileName(src));return new SuccessResponse("Art capture collected",ArtCaptureService.CopyVerified(src,dst));}catch(System.Exception e){return new ErrorResponse(e.Message);}}}
[McpForUnityTool("p3_art_run_acceptance",Description="Run registered art acceptance orchestration")] public static class P3ArtRunAcceptanceTool{public static object HandleCommand(JObject p){try{return new SuccessResponse("Art acceptance requires external review",ArtValidationOrchestrator.Run(p.Value<string>("run_id"),p.Value<string>("profile_id"),p.Value<string>("target_id")));}catch(System.Exception e){return new ErrorResponse(e.Message);}}}
[McpForUnityTool("p3_art_compare_iteration",Description="Apply one typed allowlisted UGUI iteration and collect before/after evidence")] public static class P3ArtCompareIterationTool{public static object HandleCommand(JObject p){try{var req=p["change"].ToObject<ArtIterationRequest>();var path=ArtIterationService.WritePackage(p.Value<string>("run_id"),p.Value<string>("iteration_id"),req,p.Value<string>("before_path"),p.Value<string>("after_path"));return new SuccessResponse("Art iteration recorded",new{iteration_root=path});}catch(System.Exception e){return new ErrorResponse(e.Message);}}}
[McpForUnityTool("p3_art_run_profile",Description="Run a registered P3 art profile")] public static class P3ArtRunProfileTool{public static object HandleCommand(JObject p){try{return new SuccessResponse("Art profile completed",ArtValidationOrchestrator.Run(p.Value<string>("run_id"),p.Value<string>("profile_id"),p.Value<string>("target_id")));}catch(System.Exception e){return new ErrorResponse(e.Message);}}}
